key, collection) {\n    setter(accumulator, value, iteratee(value), collection);\n  });\n  return accumulator;\n}\n\nmodule.exports = baseAggregator;\n","var baseForOwn = require('./_baseForOwn'),\n    createBaseEach = require('./_createBaseEach');\n\n/**\n * The base implementation of `_.forEach` without support for iteratee shorthands.\n *\n * @private\n * @param {Array|Object} collection The collection to iterate over.\n * @param {Function} iteratee The function invoked per iteration.\n * @returns {Array|Object} Returns `collection`.\n */\nvar baseEach = createBaseEach(baseForOwn);\n\nmodule.exports = baseEach;\n","var isArrayLike = require('./isArrayLike');\n\n/**\n * Creates a `baseEach` or `baseEachRight` function.\n *\n * @private\n * @param {Function} eachFunc The function to iterate over a collection.\n * @param {boolean} [fromRight] Specify iterating from right to left.\n * @returns {Function} Returns the new base function.\n */\nfunction createBaseEach(eachFunc, fromRight) {\n  return function(collection, iteratee) {\n    if (collection == null) {\n      return collection;\n    }\n    if (!isArrayLike(collection)) {\n      return eachFunc(collection, iteratee);\n    }\n    var length = collection.length,\n        index = fromRight ? length : -1,\n        iterable = Object(collection);\n\n    while ((fromRight ? index-- : ++index < length)) {\n      if (iteratee(iterable[index], index, iterable) === false) {\n        break;\n      }\n    }\n    return collection;\n  };\n}\n\nmodule.exports = createBaseEach;\n","import React, { Component, Fragment } from 'react';\r\nimport PropTypes from 'prop-types';\r\nimport isEqual from 'react-fast-compare';\r\n\r\nexport default class Milestone extends Component {\r\n    static propTypes = {\r\n        options: PropTypes.arrayOf(PropTypes.object),\r\n        onChange: PropTypes.func\r\n    };\r\n\r\n    static defaultProps = {\r\n        options: [],\r\n        onChange: function () {\r\n            //empty\r\n        }\r\n    };\r\n\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            currentIndex: 0,\r\n            maxIndex: props.options.length - 1,\r\n            nextDisabled: true,\r\n            prevDisabled: props.options.length <= 1\r\n        };\r\n    }\r\n\r\n    shouldComponentUpdate(nextProps, nextState) {\r\n        return !isEqual(this.state, nextState) || !isEqual(this.props, nextProps);\r\n    }\r\n\r\n    onClickComplete = () => {\r\n        this.setState({\r\n            nextDisabled: this.state.currentIndex === 0,\r\n            prevDisabled: this.state.currentIndex === this.state.maxIndex\r\n        });\r\n        this.props.onChange(this.props.options[this.state.currentIndex].value);\r\n    };\r\n\r\n    onClickNext = () => {\r\n        if (!this.state.nextDisabled) {\r\n            this.setState({\r\n                currentIndex: this.state.currentIndex - 1\r\n            }, this.onClickComplete);\r\n        }\r\n    };\r\n\r\n    onClickPrev = () => {\r\n        if (!this.state.prevDisabled) {\r\n            this.setState({\r\n                currentIndex: this.state.currentIndex + 1\r\n            }, this.onClickComplete);\r\n        }\r\n    };\r\n\r\n    render() {\r\n        const options = this.props.options;\r\n        const nextDisabled = this.state.nextDisabled ? 'disabled' : '';\r\n        const prevDisabled = this.state.prevDisabled ? 'disabled' : '';\r\n\r\n        return (\r\n            <div className=\"milestone\">\r\n                <span className={`icon-chevron-left arrow-left ${prevDisabled}`}\r\n                    disabled={this.state.prevDisabled}\r\n                    onClick={this.onClickPrev}\r\n                />\r\n                {\r\n                    options.length > 0 &&\r\n                    <Fragment>{options[this.state.currentIndex].name}</Fragment>\r\n                }\r\n                <span className={`icon-chevron-right arrow-right ${nextDisabled}`}\r\n                    disabled={this.state.nextDisabled}\r\n                    onClick={this.onClickNext}\r\n                />\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport moment from 'moment';\r\nimport isEqual from 'react-fast-compare';\r\n\r\nimport getResource from '../../resourceHelper';\r\n\r\nexport default class PerformanceAppraisalResult extends Component {\r\n    shouldComponentUpdate(nextProps) {\r\n        return !isEqual(this.props, nextProps);\r\n    }\r\n\r\n    groupPerformanceAppraisals = performanceAppraisals => {\r\n        performanceAppraisals.forEach(record => record.year = moment(record.period.startDate).year());\r\n        const pAs = performanceAppraisals.reduce(function (groups, item) {\r\n            const val = item['year'];\r\n            groups[val] = groups[val] || [];\r\n            groups[val].push(item);\r\n\r\n            return groups;\r\n        }, []);\r\n\r\n        const performanceAppraisalResults = Object.keys(pAs).map(key => {\r\n            return {\r\n                year: key,\r\n                records: pAs[key].sort(function (a, b) { return new Date(b.period.startDate) - new Date(a.period.startDate); })\r\n            };\r\n        });\r\n\r\n        return performanceAppraisalResults.sort(function (a, b) { return b.year - a.year; });\r\n    };\r\n\r\n    render() {\r\n        const performanceAppraisals = this.props.performanceAppraisals ? this.groupPerformanceAppraisals(this.props.performanceAppraisals) : [];\r\n        const title = this.props.title ? this.props.title : getResource('MyPerformanceAppraisal');\r\n\r\n        return (\r\n            <div className=\"my-pa box\">\r\n                <h5>{title}</h5>\r\n                {\r\n                    performanceAppraisals.length === 0 &&\r\n                    <div>{getResource('NoRecordFound')}</div>\r\n                }\r\n                {\r\n                    performanceAppraisals.length > 0 &&\r\n                    performanceAppraisals.map(performanceAppraisal => {\r\n                        return (\r\n                            <div key={`year${performanceAppraisal.year}`} className=\"my-pa-year\">\r\n                                <div className=\"year\">{performanceAppraisal.year}</div>\r\n                                {\r\n                                    performanceAppraisal.records.map(record => {\r\n                                        const grade = record.grade ? record.grade.description : '';\r\n                                        return (\r\n                                            <div key={`performanceAppraisal${record.paRecordId}`} className=\"term\">\r\n                                                <div>{record.period.name}</div>\r\n                                                <div className=\"grade\">{grade}</div>\r\n                                            </div>\r\n                                        );\r\n                                    })\r\n                                }\r\n                            </div>\r\n                        );\r\n                    })\r\n                }\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport memoize from 'memoize-one';\r\n\r\nexport default class Marquee extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n        this.state = {\r\n            run: true\r\n        };\r\n    }\r\n\r\n    toggleRun = () => this.setState(prevState => ({ run: !prevState.run }));\r\n\r\n    renderMessage = (message, index) => (\r\n        <span key={`message${index}`} className=\"announcement-item\">\r\n            {message}\r\n        </span>);\r\n\r\n    getStyle = memoize(\r\n        (messages, run) => {\r\n            const duration = messages.reduce((total, current) => total + current.length, 0) / 5;\r\n            const animation = `marquee ${duration}s linear infinite ${run ? 'running' : 'paused'}`;\r\n\r\n            return {\r\n                WebkitAnimation: animation,\r\n                KhtmlAnimation: animation,\r\n                MozAnimation: animation,\r\n                msAnimation: animation,\r\n                OAnimation: animation,\r\n                animation: animation\r\n            };\r\n        }\r\n    );\r\n\r\n    render() {\r\n        const style = this.getStyle(this.props.messages, this.state.run);\r\n\r\n        return (\r\n            <div className=\"marquee-block\">\r\n                <div className={`btn-pause ${!this.state.run && 'play'}`} onClick={this.toggleRun} />\r\n                <div className=\"marquee\" onClick={this.props.onClick} >\r\n                    <span className=\"annoucement\" style={style}>\r\n                        {\r\n                            this.props.messages.map(this.renderMessage)\r\n                        }\r\n                    </span>\r\n                </div>\r\n            </div>\r\n\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { Button, Modal } from 'react-bootstrap';\r\nimport getResource from '../../resourceHelper';\r\n\r\nexport default class Announcement extends PureComponent {\r\n    render() {\r\n        const content = this.props.announcements.map((e, i) => <li key={i}><p>{e}</p></li>);\r\n\r\n        return (\r\n            <Modal\r\n                show={this.props.showModal} onHide={this.props.onCloseModal}\r\n                dialogClassName=\"custom-modal announcement-modal\"\r\n            >\r\n                <Modal.Header closeButton>\r\n                    <Modal.Title>Announcement</Modal.Title>\r\n                </Modal.Header>\r\n                <Modal.Body>\r\n                    <ul>{content}</ul>\r\n                </Modal.Body>\r\n                <Modal.Footer>\r\n                    <Button onClick={this.props.onCloseModal} className=\"btn btn-primary\">{getResource('Close')}</Button>\r\n                </Modal.Footer>\r\n            </Modal>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nexport default class EmployeeInfo extends PureComponent {\r\n    render() {\r\n        const employee = this.props.employee;\r\n        return (\r\n            <div className=\"user-info box\">\r\n                <img src={employee.avatar} alt=\"avatar\" className=\"avatar\" />\r\n                <div>\r\n                    <div className=\"nick-name role-member\">{employee.nickName}</div>\r\n                    <div className=\"user-name\">{employee.fullName}</div>\r\n                    <div className=\"role role-PM\">{employee.jobTitle}</div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport PropTypes from 'prop-types';\r\nimport isEqual from 'react-fast-compare';\r\n\r\nimport { getNominationClassName } from '../../common-functions';\r\nimport { NominationStatuses } from '../../constants';\r\nimport getResource from '../../resourceHelper';\r\n\r\nexport default class NominationResult extends Component {\r\n    static propTypes = {\r\n        nominations: PropTypes.arrayOf(PropTypes.object)\r\n    };\r\n\r\n    static defaultProps = {\r\n        nominations: []\r\n    };\r\n\r\n    shouldComponentUpdate(nextProps) {\r\n        return !isEqual(this.props, nextProps);\r\n    }\r\n\r\n    groupNominationByStatusId = nominations => {\r\n        const nominationReduces = nominations.reduce(function (groups, item) {\r\n            const val = item['statusId'];\r\n            groups[val] = groups[val] || [];\r\n            groups[val].push(item.period);\r\n\r\n            return groups;\r\n        }, []);\r\n\r\n        const nominationReults = Object.keys(nominationReduces).map(key => {\r\n            const statusId = parseInt(key, 10);\r\n\r\n            return {\r\n                statusId: statusId,\r\n                statusText: NominationStatuses.find(x => x.value === statusId).text,\r\n                periods: nominationReduces[key]\r\n            };\r\n        });\r\n\r\n        return nominationReults;\r\n    };\r\n\r\n    render() {\r\n        const nominations = this.groupNominationByStatusId(this.props.nominations);\r\n\r\n        return (\r\n            <div className=\"nomination box\">\r\n                <h5>{getResource('Achievements')}</h5>\r\n                {\r\n                    nominations && nominations.map((nomination, index) => {\r\n                        return (\r\n                            <div className=\"result-item\" key={`nominationResult${index}`}>\r\n                                <span className={getNominationClassName(nomination.statusId)}>\r\n                                    {nomination.statusText}\r\n                                </span>: <span>{nomination.periods.map(period => period.shortTitle).join(', ')}</span>\r\n                            </div>\r\n                        );\r\n                    })\r\n                }\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport axios from 'axios';\r\nimport { Doughnut } from 'react-chartjs-2';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../common-functions';\r\nimport { ChartColors } from '../../constants';\r\nimport getResource from '../../resourceHelper';\r\nimport Milestone from '../../shared/components/milestone';\r\n\r\nexport default class WorkLoad extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            chartData: null,\r\n            periodId: this.props.periods[0].periodId\r\n        };\r\n\r\n        this.chartOptions.afterInit = this.props.afterInitChart;\r\n    }\r\n\r\n    componentDidMount() {\r\n        this.getWorkload();\r\n    }\r\n\r\n    componentDidUpdate() {\r\n        this.generateChartLegend();\r\n    }\r\n\r\n    generateChartLegend = () => {\r\n        if (this.refs.chart) {\r\n            document.getElementById('legend-container').innerHTML = this.refs.chart.chartInstance.generateLegend();\r\n        } else {\r\n            document.getElementById('legend-container').innerHTML = '';\r\n        }\r\n    };\r\n\r\n    getWorkload = () => {\r\n        axios.get(resolveClientUrl('Home/GetWorkload'), {\r\n            params: {\r\n                periodId: this.state.periodId,\r\n                memberId: this.props.memberId ? this.props.memberId : null\r\n            }\r\n        }).then(response => this.setState({\r\n            chartData: this.getChartData(response.data)\r\n        }, () => this.chartOptions.afterInit = null\r\n        )).catch(axiosError);\r\n    };\r\n\r\n    getChartData = workload => {\r\n        if (workload.length > 5) {\r\n            const labels = workload.slice(0, 5).map(e => e.name);\r\n            labels.push('Others');\r\n            const data = workload.slice(0, 5).map(e => e.totalHours);\r\n\r\n            const othersValue = workload.slice(5, workload.length).reduce(function (total, current) {\r\n                return total + current.totalHours;\r\n            }, 0);\r\n\r\n            data.push(othersValue);\r\n\r\n            return {\r\n                datasets: [{\r\n                    data: data,\r\n                    backgroundColor: ChartColors\r\n                }],\r\n                labels: labels\r\n            };\r\n        }\r\n\r\n        return {\r\n            datasets: [{\r\n                data: workload.map(e => e.totalHours),\r\n                backgroundColor: ChartColors\r\n            }],\r\n            labels: workload.map(e => e.name)\r\n        };\r\n    };\r\n\r\n    onPeriodChange = periodId => {\r\n        this.setState({\r\n            periodId: periodId\r\n        }, this.getWorkload);\r\n    };\r\n\r\n    chartOptions = {\r\n        animation: {\r\n            duration: 500,\r\n            onComplete: function () {\r\n                if (this.options.afterInit) {\r\n                    this.options.afterInit();\r\n                    this.options.afterInit = null;\r\n                }\r\n            }\r\n        },\r\n        cutoutPercentage: 60,\r\n        tooltips: {\r\n            callbacks: {\r\n                label: function (tooltipItem, data) {\r\n                    const dataset = data.datasets[tooltipItem.datasetIndex];\r\n                    const currentValue = dataset.data[tooltipItem.index];\r\n\r\n                    return `${currentValue} hours`;\r\n                },\r\n                title: function (tooltipItem, data) {\r\n                    return data.labels[tooltipItem[0].index];\r\n                }\r\n            }\r\n        },\r\n        legend: {\r\n            position: 'bottom',\r\n            labels: {\r\n                usePointStyle: true,\r\n                generateLabels: function (chart) {\r\n                    const data = chart.data;\r\n\r\n                    if (data.labels.length && data.datasets.length) {\r\n                        const meta = chart.getDatasetMeta(0);\r\n                        const ds = data.datasets[0];\r\n                        const total = ds.data.reduce((accumulator, currentValue) => accumulator + currentValue);\r\n\r\n                        return data.labels.map(function (label, i) {\r\n                            const percentage = (ds.data[i] / total * 100).toFixed(1);\r\n                            const arc = meta.data[i];\r\n                            const custom = arc && arc.custom || {};\r\n                            const arcOpts = chart.options.elements.arc;\r\n                            const fill = custom.backgroundColor ? custom.backgroundColor : ds.backgroundColor[i] || arcOpts.backgroundColor;\r\n                            const stroke = arcOpts.borderColor;\r\n                            const bw = arcOpts.borderWidth;\r\n\r\n                            return {\r\n                                text: `${label}: ${percentage}% `,\r\n                                fillStyle: fill,\r\n                                strokeStyle: stroke,\r\n                                lineWidth: bw,\r\n                                hidden: isNaN(ds.data[i]) || meta.data[i].hidden,\r\n                                index: i\r\n                            };\r\n                        });\r\n                    }\r\n\r\n                    return [];\r\n                }\r\n            },\r\n            display: false\r\n        },\r\n        maintainAspectRatio: false,\r\n        legendCallback: function (chart) {\r\n            const data = chart.data;\r\n            let legends = [];\r\n            if (data.labels.length && data.datasets.length) {\r\n                const meta = chart.getDatasetMeta(0);\r\n                const ds = data.datasets[0];\r\n                const total = ds.data.reduce((accumulator, currentValue) => accumulator + currentValue);\r\n\r\n                legends = data.labels.map(function (label, i) {\r\n                    const percentage = (ds.data[i] / total * 100).toFixed(1);\r\n                    const arc = meta.data[i];\r\n                    const custom = arc && arc.custom || {};\r\n                    const arcOpts = chart.options.elements.arc;\r\n                    const fill = custom.backgroundColor ? custom.backgroundColor : ds.backgroundColor[i] || arcOpts.backgroundColor;\r\n                    const stroke = arcOpts.borderColor;\r\n\r\n                    return `\r\n                        <div class=\"legend-item\">\r\n                            <span style=\"background-color: ${fill};border-color: ${stroke};\" ></span>\r\n                            ${label}: ${percentage}%\r\n                        </div>\r\n                    `;\r\n                });\r\n            }\r\n\r\n            return legends.join('');\r\n        }\r\n    };\r\n\r\n    renderWorkloadChart = () => {\r\n        const chartData = this.state.chartData;\r\n\r\n        if (chartData !== null && chartData.labels.length > 0) {\r\n            return <Doughnut ref='chart' data={chartData} height={200} options={this.chartOptions} />;\r\n        }\r\n\r\n        return <span>{getResource('NoRecordFound')}</span>;\r\n    };\r\n\r\n    render() {\r\n        const periodOptions = this.props.periods.map(period => {\r\n            return { name: period.name, value: period.periodId };\r\n        });\r\n        return (\r\n            <div className=\"workload box\">\r\n                <div className=\"title clearfix\">\r\n                    <h5>{getResource('Workload')}</h5>\r\n                    <Milestone\r\n                        options={periodOptions}\r\n                        onChange={this.onPeriodChange}\r\n                    />\r\n                </div>\r\n                <div style={{ position: 'relative' }}>\r\n                    {\r\n                        this.renderWorkloadChart()\r\n                    }\r\n                </div>\r\n                <div id=\"legend-container\" className=\"legend-container\" />\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { Fragment, Component } from 'react';\r\nimport moment from 'moment';\r\nimport axios from 'axios';\r\nimport isEqual from 'react-fast-compare';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport { DateFormat } from '../../../constants';\r\nimport getResource from '../../../resourceHelper';\r\nimport Discipline from './DisciplineModal';\r\n\r\nexport default class HRMSummary extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n        this.state = {\r\n            hrmDetail: {},\r\n            isShowModal: false\r\n        };\r\n    }\r\n\r\n    componentDidMount() {\r\n        axios.get(resolveClientUrl('Common/GetHRMSummary'), {\r\n            params: {\r\n                memberId: this.props.memberId ? this.props.memberId : null\r\n            }\r\n        }).then(response =>\r\n            this.setState({\r\n                hrmDetail: response.data\r\n            })).catch(axiosError);\r\n    }\r\n\r\n    shouldComponentUpdate(nextProps, nextState) {\r\n        return !isEqual(this.state, nextState) || !isEqual(this.props, nextProps);\r\n    }\r\n\r\n    onShowModal = () => {\r\n        this.setState({\r\n            isShowModal: true\r\n        });\r\n    };\r\n\r\n    onCloseModal = () => {\r\n        this.setState({\r\n            isShowModal: false\r\n        });\r\n    };\r\n\r\n    renderToeicScore = hrmDetail => {\r\n        let toeicClass = '';\r\n        if (hrmDetail.toeicPolicy < 0) {\r\n            toeicClass = 'toeic-failed';\r\n        }\r\n\r\n        const expireDate = moment(hrmDetail.toeicExamDate).add(3, 'years').format(DateFormat);\r\n        const showExpireDate = parseInt(hrmDetail.toeicScore, 10) < 900 ? `(exp ${expireDate})` : '';\r\n\r\n        if (hrmDetail.toeicScore > 0) {\r\n            return (\r\n                <Fragment>\r\n                    <span className={toeicClass}>{hrmDetail.toeicScore}</span> {showExpireDate}\r\n                </Fragment>\r\n            );\r\n        } else {\r\n            return (\r\n                <span className={toeicClass}>{getResource('N/A')}</span>\r\n            );\r\n        }\r\n    };\r\n\r\n    renderDiscipline = incident => {\r\n        if (incident > 0) {\r\n            return <a onClick={this.onShowModal}>{incident}</a>;\r\n        }\r\n\r\n        return incident;\r\n    };\r\n\r\n    render() {\r\n        const hrm = this.state.hrmDetail;\r\n        const memberId = this.props.memberId ? this.props.memberId : null;\r\n        return (\r\n            <div className=\"hrm-summary box\">\r\n                <h5>{getResource('Hrm')}</h5>\r\n                <ul className=\"hrm-info\">\r\n                    <li>{getResource('Toeic')}<span className=\"bold\">: {this.renderToeicScore(hrm)}</span></li>\r\n                    <li>{getResource('AverageWorkDays')}<span className=\"bold\">: {hrm.averageWorkingDays}</span></li>\r\n                    <li>{getResource('AverageSpentTime')}<span className=\"bold\">: {hrm.averageSpentTime}</span></li>\r\n                    <li>{getResource('MissingCheckInOut')}<span className=\"bold\">: {hrm.missingCheckInCheckOut}</span></li>\r\n                    <li>{getResource('LateInEarlyOut')}<span className=\"bold\">: {hrm.totalLateInEarlyOut}</span></li>\r\n                    <li>{getResource('UnpaidLeave')}<span className=\"bold\">: {hrm.unpaidLeave}</span></li>\r\n                    <li>{getResource('UnplannedLeave')}<span className=\"bold\">: {hrm.unplannedAnnualLeave}</span></li>\r\n                    <li>{getResource('SickLeave')}<span className=\"bold\">: {hrm.sickLeave}</span></li>\r\n                    <li>{getResource('Discipline')}<span className=\"bold\">: {this.renderDiscipline(hrm.incident)}</span></li>\r\n                </ul>\r\n                {\r\n                    this.state.isShowModal &&\r\n                    <Discipline\r\n                        memberId={memberId}\r\n                        isShowModal={this.state.isShowModal}\r\n                        onCloseModal={this.onCloseModal}\r\n                    />\r\n                }\r\n            </div >\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport { Button, Modal } from 'react-bootstrap';\r\nimport axios from 'axios';\r\nimport moment from 'moment';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport getResource from '../../../resourceHelper';\r\nimport { DateFormat } from '../../../constants';\r\n\r\nexport default class DisciplineModal extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n        this.state = {\r\n            disciplines: []\r\n        };\r\n    }\r\n\r\n    componentDidMount() {\r\n        axios.get(resolveClientUrl('Common/GetDisciplineByEmployeeId'), {\r\n            params: {\r\n                memberId: this.props.memberId ? this.props.memberId : null\r\n            }\r\n        }).then(response =>\r\n            this.setState({\r\n                disciplines: response.data\r\n            })).catch(axiosError);\r\n    }\r\n\r\n    renderDisciplines = disciplines => {\r\n        if (disciplines.length > 0) {\r\n            return (\r\n                disciplines.map((discipline, index) => {\r\n                    return (\r\n                        <tr>\r\n                            <td className=\"text-center\">{index + 1}</td>\r\n                            <td>{discipline.description}</td>\r\n                            <td className=\"text-center\">{moment(discipline.effectiveDate).format(DateFormat)}</td>\r\n                        </tr>\r\n                    );\r\n                })\r\n            );\r\n        }\r\n\r\n        return (\r\n            <tr>\r\n                <td colSpan=\"3\" className=\"text-center\">{getResource('NoRecordFound')}</td>\r\n            </tr>\r\n        );\r\n    };\r\n\r\n    render() {\r\n        const disciplines = this.state.disciplines;\r\n        return (\r\n            <Modal keyboard backdrop=\"static\"\r\n                show={this.props.isShowModal} onHide={this.props.onCloseModal}\r\n                dialogClassName=\"custom-modal modal-md form-performance edit \"\r\n            >\r\n                <Modal.Header>\r\n                    <Modal.Title>{getResource('Discipline')}</Modal.Title>\r\n                </Modal.Header>\r\n                <Modal.Body>\r\n                    <table className=\"table table-bordered\">\r\n                        <thead>\r\n                            <tr>\r\n                                <th>#</th>\r\n                                <th>{getResource('Description')}</th>\r\n                                <th>{getResource('IssueDate')}</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            {\r\n                                this.renderDisciplines(disciplines)\r\n                            }\r\n                        </tbody>\r\n                    </table>\r\n                </Modal.Body>\r\n                <Modal.Footer>\r\n                    <Button className=\"btn-cancel\" onClick={this.props.onCloseModal}>{getResource('Close')}</Button>\r\n                </Modal.Footer>\r\n            </Modal>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport { Button, Modal } from 'react-bootstrap';\r\nimport axios from 'axios';\r\nimport { toast } from 'react-toastify';\r\nimport { stringify } from 'qs';\r\n\r\nimport { resolveClientUrl, axiosError } from '../../../common-functions';\r\nimport { PostRequestHeaders } from '../../../constants';\r\nimport getResource from '../../../resourceHelper';\r\n\r\nexport default class NotificationSetting extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            notificationSettings: []\r\n        };\r\n    }\r\n\r\n    componentDidMount() {\r\n        axios.get(resolveClientUrl('Notification/GetSetting'))\r\n            .then(response => {\r\n                this.setState({\r\n                    notificationSettings: response.data\r\n                });\r\n            }).catch(axiosError);\r\n    }\r\n\r\n    handleChange = (event, typeId, name) => {\r\n        const settings = [...this.state.notificationSettings];\r\n        settings.find(setting => setting.type === typeId)[name] = event.target.checked;\r\n        this.setState({\r\n            notificationSettings: settings\r\n        });\r\n    };\r\n\r\n    saveSetting = () => {\r\n        axios({\r\n            url: resolveClientUrl('Notification/EditSetting'),\r\n            method: 'POST',\r\n            data: stringify({\r\n                __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,\r\n                settings: this.state.notificationSettings\r\n            }),\r\n            headers: PostRequestHeaders\r\n        }).then(response => {\r\n            const result = response.data;\r\n            if (result.isSuccessful) {\r\n                toast.success(getResource('UpdatedSuccessfully'));\r\n                this.props.onCloseModal();\r\n            } else {\r\n                toast.error(result.message);\r\n            }\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <Modal keyboard={false} backdrop=\"static\"\r\n                show={this.props.isShowModal} onHide={this.props.onCloseModal}\r\n                dialogClassName=\"custom-modal modal-xs form-performance edit\"\r\n                id=\"notification-settings\"\r\n            >\r\n                <Modal.Header>\r\n                    <Modal.Title>{getResource('NotificationSetting')}</Modal.Title>\r\n                </Modal.Header>\r\n                <Modal.Body>\r\n                    <table className=\"table table-bordered\">\r\n                        <thead>\r\n                            <tr>\r\n                                <th>{getResource('Type')}</th>\r\n                                <th>{getResource('Notification')}</th>\r\n                                <th>{getResource('Email')}</th>\r\n                                <th>{getResource('SkypeMessage')}</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            {\r\n                                this.state.notificationSettings.map(setting => {\r\n                                    return (\r\n                                        <tr>\r\n                                            <td>{setting.description}</td>\r\n                                            <td className=\"text-center\">\r\n                                                <input type=\"checkbox\" className=\"checkbox-custom\"\r\n                                                    id={`chb-${setting.type}-noti`}\r\n                                                    checked={setting.receiveNotification}\r\n                                                    onClick={event => this.handleChange(event, setting.type, 'receiveNotification')}\r\n                                                />\r\n                                                <label htmlFor={`chb-${setting.type}-noti`} />\r\n                                            </td>\r\n                                            <td className=\"text-center\">\r\n                                                <input type=\"checkbox\" className=\"checkbox-custom\"\r\n                                                    id={`chb-${setting.type}-email`}\r\n                                                    checked={setting.receiveEmail}\r\n                                                    onClick={event => this.handleChange(event, setting.type, 'receiveEmail')}\r\n                                                />\r\n                                                <label htmlFor={`chb-${setting.type}-email`} />\r\n                                            </td>\r\n                                            <td className=\"text-center\">\r\n                                                <input type=\"checkbox\" className=\"checkbox-custom\"\r\n                                                    id={`chb-${setting.type}-skype`}\r\n                                                    checked={setting.receiveSkypeMessage}\r\n                                                    onClick={event => this.handleChange(event, setting.type, 'receiveSkypeMessage')}\r\n                                                />\r\n                                                <label htmlFor={`chb-${setting.type}-skype`} />\r\n                                            </td>\r\n                                        </tr>\r\n                                    );\r\n                                })\r\n                            }\r\n                        </tbody>\r\n                    </table>\r\n                </Modal.Body>\r\n                <Modal.Footer>\r\n                    <Button className=\"btn-cancel\" onClick={this.props.onCloseModal}>{getResource('Close')}</Button>\r\n                    <Button className=\"btn btn-primary\" onClick={this.saveSetting}>{getResource('Submit')}</Button>\r\n                </Modal.Footer>\r\n            </Modal>\r\n        );\r\n    }\r\n}","import React from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport NotificationCenter from './notification-center';\r\n\r\nReactDOM.render(<NotificationCenter />, document.getElementById('notification-center'));","import React, { Component } from 'react';\r\nimport axios from 'axios';\r\nimport { toast } from 'react-toastify';\r\n\r\nimport { axiosError, getCurrentUserInfo, resolveClientUrl, getUrlByActionTypeId } from '../../common-functions';\r\nimport { NotificationActionType, NotificationStatus } from '../../constants';\r\nimport ToastLayout from '../../shared/layouts/ToastLayout';\r\nimport EmployeeInfo from '../home/EmployeeInfo';\r\nimport PerformanceAppraisalResult from '../home/PerformanceAppraisalResult';\r\nimport Marquee from '../../shared/components/Marquee';\r\nimport NominationResult from '../home/NominationResult';\r\nimport WorkLoad from '../home/workload';\r\nimport HrmSummary from '../home/hrm/HRMSummary';\r\nimport Announcement from '../../shared/components/Announcement';\r\nimport NotificationBoard from './notification-board';\r\nimport getResource from '../../resourceHelper';\r\nimport CustomScrollbars from '../../shared/components/CustomScrollbars';\r\n\r\nexport default class NotificationCenter extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            periods: [],\r\n            nominations: [],\r\n            performanceAppraisals: [],\r\n            announcements: [],\r\n            showAnnouncementModal: false,\r\n            notifications: [],\r\n            hasMore: true,\r\n            pageIndex: 0,\r\n            unreadNoti: 0\r\n        };\r\n\r\n        this.pageSize = 20;\r\n    }\r\n\r\n    componentDidMount() {\r\n        const promises = [\r\n            axios(resolveClientUrl('Common/GetAllPeriods')),\r\n            axios(resolveClientUrl('home/GetNominationResult')),\r\n            axios(resolveClientUrl('home/GetPerformanceAppraisalResult')),\r\n            axios(resolveClientUrl('common/GetAnnouncements')),\r\n            axios(resolveClientUrl('Notification/GetNotification'), {\r\n                params: {\r\n                    pageIndex: 0,\r\n                    pageSize: this.pageSize\r\n                }\r\n            })\r\n        ];\r\n\r\n        Promise.all(promises)\r\n            .then(([periodResponse, nominationResponse, performanceAppraisalsResponse, announcementsResponse, notificationResponse]) => {\r\n                const notiData = notificationResponse.data;\r\n                this.setState({\r\n                    periods: periodResponse.data,\r\n                    announcements: announcementsResponse.data.length > 0 ? announcementsResponse.data : [getResource('DefaultAnnouncement')],\r\n                    nominations: nominationResponse.data,\r\n                    performanceAppraisals: performanceAppraisalsResponse.data,\r\n                    notifications: notiData.notifications,\r\n                    unreadNoti: notiData.unreadNoti,\r\n                    hasMore: notiData.notifications.length < notiData.total\r\n                });\r\n            }).catch(axiosError);\r\n\r\n        this.addEventListener();\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        this.removeEventListener();\r\n    }\r\n\r\n    getNotifications = () => {\r\n        axios.get(resolveClientUrl('Notification/GetNotification'), {\r\n            params: {\r\n                pageIndex: this.state.pageIndex,\r\n                pageSize: this.pageSize\r\n            }\r\n        }).then(response => {\r\n            const data = response.data;\r\n            const notifications = this.state.notifications;\r\n            notifications.push(...data.notifications);\r\n\r\n            this.setState({\r\n                notifications: notifications,\r\n                unreadNoti: data.unreadNoti,\r\n                hasMore: notifications.length < data.total\r\n            });\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    triggerNotificationBell = notificationId => {\r\n        const notiBell = document.getElementById('trigger-notification-bell');\r\n        if (notiBell) {\r\n            notiBell.setAttribute('notificationId', notificationId);\r\n            notiBell.click();\r\n        }\r\n    };\r\n\r\n    addEventListener = () => {\r\n        const notiTrigger = document.getElementById('trigger-notification-center');\r\n        if (notiTrigger) {\r\n            notiTrigger.addEventListener('click', () => {\r\n                const notificationId = parseInt(notiTrigger.getAttribute('notificationId'), 10);\r\n                if (!notificationId) {\r\n                    this.markAsReadSuccessCenter();\r\n                } else {\r\n                    this.handleChangeStatusSuccess(notificationId);\r\n                }\r\n            }, false);\r\n        }\r\n    };\r\n\r\n    removeEventListener = () => {\r\n        const notiTrigger = document.getElementById('trigger-notification-center');\r\n        if (notiTrigger) {\r\n            notiTrigger.removeEventListener('click');\r\n        }\r\n    };\r\n\r\n    handleLoadMoreNotification = () => {\r\n        if (this.state.hasMore) {\r\n            this.setState({\r\n                pageIndex: this.state.pageIndex + 1\r\n            }, () => {\r\n                if (this.state.hasMore) {\r\n                    this.getNotifications();\r\n                }\r\n            });\r\n        }\r\n    };\r\n\r\n    handleRedirectToActionCenter = notificationId => {\r\n        const notificationsCenter = this.state.notifications.slice();\r\n        const notiIndexCenter = notificationsCenter.findIndex(noti => noti.notificationId === notificationId);\r\n        if (notiIndexCenter !== -1) {\r\n            const { actionTypeId, recordId } = notificationsCenter[notiIndexCenter];\r\n\r\n            const urlCenter = getUrlByActionTypeId(actionTypeId, recordId, NotificationActionType);\r\n\r\n            if (urlCenter) {\r\n                window.location = urlCenter;\r\n            }\r\n        }\r\n    };\r\n\r\n    markAsReadSuccessCenter = () => {\r\n        const notifications = this.state.notifications.slice();\r\n        for (let i = 0; i < notifications.length; i++) {\r\n            notifications[i].statusId = NotificationStatus.Read;\r\n        }\r\n\r\n        this.setState({\r\n            notifications: notifications,\r\n            unreadNoti: 0\r\n        });\r\n\r\n        this.triggerNotificationBell();\r\n    };\r\n\r\n    handleMarkAsRead = () => {\r\n        if (this.state.unreadNoti > 0) {\r\n            axios.get(resolveClientUrl('Notification/MarkAsRead'))\r\n                .then(response => {\r\n                    const data = response.data;\r\n                    if (data.isSuccessful) {\r\n                        this.markAsReadSuccessCenter();\r\n                    } else {\r\n                        toast.error(data.message);\r\n                    }\r\n                }).catch(axiosError);\r\n        }\r\n    };\r\n\r\n    handleChangeStatusSuccess = notificationId => {\r\n        const notifications = this.state.notifications.slice();\r\n        const index = notifications.findIndex(x => x.notificationId === notificationId);\r\n\r\n        if (index >= 0) {\r\n            notifications[index].statusId = NotificationStatus.Read;\r\n            this.setState({\r\n                notifications: notifications,\r\n                unreadNoti: this.state.unreadNoti - 1\r\n            });\r\n\r\n            this.triggerNotificationBell(notificationId);\r\n        }\r\n    };\r\n\r\n    handleChangeStatus = (notificationId, statusId, isRedirect) => {\r\n        if (statusId === NotificationStatus.Unread) {\r\n            axios.get(resolveClientUrl('Notification/ReadNotification'), {\r\n                params: {\r\n                    notificationId: notificationId\r\n                }\r\n            }).then(response => {\r\n                const data = response.data;\r\n                if (data.isSuccessful) {\r\n                    if (isRedirect) {\r\n                        this.handleRedirectToActionCenter(notificationId);\r\n                    } else {\r\n                        this.handleChangeStatusSuccess(notificationId);\r\n                    }\r\n                } else {\r\n                    toast.error(data.message);\r\n                }\r\n            }).catch(axiosError);\r\n        } else if (isRedirect) {\r\n            this.handleRedirectToActionCenter(notificationId);\r\n        }\r\n    };\r\n\r\n    handleCloseAnnouncementModal = () => this.setState({ showAnnouncementModal: false });\r\n\r\n    handleOpenAnnouncementModal = () => this.setState({ showAnnouncementModal: true });\r\n\r\n    render() {\r\n        const currentUserInfo = getCurrentUserInfo();\r\n\r\n        return (\r\n            <div className=\"row\">\r\n                <ToastLayout />\r\n                <div className=\"my-page main-layout\">\r\n                    <div className=\"general-info\">\r\n                        <CustomScrollbars>\r\n                            <EmployeeInfo employee={currentUserInfo} />\r\n                            <PerformanceAppraisalResult performanceAppraisals={this.state.performanceAppraisals} />\r\n                        </CustomScrollbars>\r\n                    </div>\r\n                    <div className=\"main-content\">\r\n                        <div className=\"fixed-section\">\r\n                            <Marquee messages={this.state.announcements} onClick={this.handleOpenAnnouncementModal} />\r\n                        </div>\r\n                        <div className=\"noti-record\">\r\n                            <NotificationBoard notifications={this.state.notifications}\r\n                                onLoadMore={this.handleLoadMoreNotification}\r\n                                onChangeStatus={this.handleChangeStatus}\r\n                                onMarkAsRead={this.handleMarkAsRead}\r\n                            />\r\n                        </div>\r\n                    </div>\r\n                    <div className=\"work-info\">\r\n                        <CustomScrollbars>\r\n                            <div className=\"work-info-content\">\r\n                                {\r\n                                    this.state.nominations.length > 0 &&\r\n                                    <NominationResult nominations={this.state.nominations} />\r\n                                }\r\n                                {\r\n                                    this.state.periods.length > 0 &&\r\n                                    <WorkLoad periods={this.state.periods} />\r\n                                }\r\n                                <HrmSummary />\r\n                            </div>\r\n                        </CustomScrollbars>\r\n                    </div>\r\n                </div>\r\n                <Announcement showModal={this.state.showAnnouncementModal}\r\n                    onCloseModal={this.handleCloseAnnouncementModal}\r\n                    announcements={this.state.announcements}\r\n                />\r\n            </div >\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport InfiniteScroll from 'react-infinite-scroller';\r\nimport CustomScrollbars from '../../shared/components/CustomScrollbars';\r\nimport { NotificationStatus } from '../../constants';\r\nimport { calendar, getAvatar } from '../../common-functions';\r\nimport getResource from '../../resourceHelper';\r\nimport ToastLayout from '../../shared/layouts/ToastLayout';\r\nimport NotificationSetting from '../../shared/components/notification/NotificationSetting';\r\n\r\nexport default class NotificationBoard extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            isShowSettingModal: false\r\n        };\r\n    }\r\n\r\n    handleClickSetting = () => {\r\n        this.setState({\r\n            isShowSettingModal: true\r\n        });\r\n    };\r\n\r\n    handleCancelSetting = () => {\r\n        this.setState({\r\n            isShowSettingModal: false\r\n        });\r\n    };\r\n\r\n    render() {\r\n        const notifications = this.props.notifications;\r\n\r\n        return (\r\n            <ToastLayout>\r\n                <div className=\"noti-header\">\r\n                    <span className=\"title\">{getResource('Notification')}</span>\r\n                    <span className=\"noti-function\">\r\n                        <a className=\"mark-read\" onClick={this.props.onMarkAsRead}>Mark as read</a>\r\n                        <span className=\"dash\" />\r\n                        <a className=\"setting\" onClick={this.handleClickSetting}>Settings</a>\r\n                    </span>\r\n                    {\r\n                        this.state.isShowSettingModal &&\r\n                        <NotificationSetting\r\n                            isShowModal={this.state.isShowSettingModal}\r\n                            onCloseModal={this.handleCancelSetting}\r\n                        />\r\n                    }\r\n                </div>\r\n                <div className=\"noti-body\">\r\n                    <CustomScrollbars>\r\n                        {\r\n                            notifications &&\r\n                            <InfiniteScroll initialLoad={false}\r\n                                pageStart={1}\r\n                                loadMore={this.props.onLoadMore}\r\n                                hasMore={this.props.hasMore}\r\n                                useWindow={false}\r\n                            >\r\n                                {\r\n                                    notifications.map(item => {\r\n                                        const notiStatus = item.statusId === NotificationStatus.Unread ? 'unread' : '';\r\n                                        return (\r\n                                            <div className={`noti-center-item ${notiStatus} noti-${item.notificationId}`}\r\n                                                onClick={() => this.props.onChangeStatus(item.notificationId, item.statusId, false)}\r\n                                            >\r\n                                                <img className=\"avatar\"\r\n                                                    src={getAvatar(item.creatorId, item.creatorCode)}\r\n                                                />\r\n                                                <div className=\"description\">\r\n                                                    <a onClick={() => this.props.onChangeStatus(item.notificationId, item.statusId, true)}>\r\n                                                        {item.content}\r\n                                                    </a>\r\n                                                    <div className=\"created-date\">{calendar(item.createdDate)}</div>\r\n                                                </div>\r\n                                            </div>\r\n                                        );\r\n                                    })\r\n                                }\r\n                            </InfiniteScroll>\r\n                        }\r\n                    </CustomScrollbars>\r\n                </div>\r\n            </ToastLayout>\r\n        );\r\n    }\r\n}"],"sourceRoot":""}
